-- 公報上的政見由系統直接派「從公報補政見」任務（2026-10-06，維護者點頭）
--
-- 起因：a-zhen 交「查無異動」說台南安南區四草里 2022 里長吳文振查無政見，checked_urls 六個全是 google 搜尋；
-- 實際上 https://eebulletin.cec.gov.tw/111/06臺南市/05村里長/36安南/四草里.pdf 公報裡就列了他四條政見（號次 2）。
-- 選舉公報是候選人自己登記的政見原文、每位參選人都有，推得出公報網址就不該讓代理自己去找、更不該讓「查無」關掉缺口。
--
-- 盤點（10-06，依兩個公報站的 ?action=sitemap 全站清單，與 cec_candidates 逐單位對）：
--   eebulletin.cec.gov.tw 有 103／107／111 年地方選舉（111 年 4,768 份）；bulletin.cec.gov.tw 有 113 年第 11 屆立委。
--   2022 地方：縣市長 89／89 位、縣市議員 1,509／1,524、鄉鎮市長 463／489、鄉鎮市民代表 3,107／3,225、
--   原住民區長 20／20、原住民區民代表 92／92、村里長 10,886／14,021 位推得出公報；2024 區域立委 309／309。
--   推不出的（嘉義縣、屏東縣、南投縣、宜蘭縣等依選區分檔而不知道村里在哪一區；新竹市、嘉義市聯合里公報；
--   中選會名單的罕用字缺字，如「子里」）列在 PR 說明，不派。
--   派工面（10-06 唯讀實跑）：既有派工只對 2022 縣市長／縣市議員／鄉鎮市長、2024 立委的**當選人**派補任期政見，
--   而且只給公報站首頁；村里長、代表、原住民區長／區民代表、落選人一律沒有任何任務會去補政見。
--
-- 做法（只加不刪；不動 contribution_auto_tasks_arms，避免跟同時在改派工臂的 PR 互相蓋掉）：
--   1. 新表 election_bulletins：一列＝中選會名單上的一個選舉單位（跟 cec_candidates 同一套 region／sub_region／village）
--      → 那一份（或正反面、分份的幾份）公報的站內路徑。資料由 scripts/build-election-bulletins.ts 依全站清單產生，
--      規則在 supabase/functions/_shared/election-bulletin.ts（有測試）；對不到的不寫——寧可不派，不要派錯
--      （派錯一份，代理找不到人就回「查無」，缺口 14 天不再派）。
--   2. 視圖 politician_bulletins：我們的參選紀錄 → 中選會名單上**唯一**對得上的那一位（同屆、同選舉別、同縣市、
--      同姓名鍵，有鄉鎮、村里就也要對上）→ 公報網址＋號次。同名多人不給。
--   3. 函式 politician_bulletins_for(人物)：任務現況（task-context）用，連網站訪客請求的補政見任務也看得到公報。
--   4. contribution_auto_tasks_term_policies() 改寫（沿用 term_policy_missing，task_id 格式不變）：
--      原本的對象（當選人）照舊，推得出公報就附上；另外對推得出公報、沒有該屆政見的參選人（含落選、村里長、代表、
--      原住民區長／區民代表）也派。零政見的 2026 候選人照舊留給 policy_missing。
--      村里長一次最多開 term_policy_village_cap()（300）件、當選人先：上萬件同時進佇列會把其他任務擠到好幾天後
--      （派過的任務回到隊尾）；補完或冷卻結束的位子由下一位遞補。
--
-- 用到的既有欄位（10-06 唯讀確認存在）：politician_elections(id, politician_id, election_id, election_type,
-- election_result, region_id, candidate_status)、politicians(id, name, party, region, sub_region, village, merged_into)、
-- regions(id, region, sub_region, village)、cec_candidates(election_id, election_type, region, sub_region, village,
-- name_norm, cand_no, elected)、policies(politician_id, election_id, removed_at)、task_dispatches(task_id)、cec_name_key()。

CREATE TABLE IF NOT EXISTS election_bulletins (
  id            BIGSERIAL PRIMARY KEY,
  election_id   INTEGER NOT NULL,
  election_type TEXT NOT NULL,
  region        TEXT NOT NULL,
  sub_region    TEXT NOT NULL DEFAULT '',
  village       TEXT NOT NULL DEFAULT '',
  paths         TEXT[] NOT NULL CHECK (cardinality(paths) BETWEEN 1 AND 4),
  match_basis   TEXT NOT NULL,
  listed_on     DATE NOT NULL DEFAULT DATE '2026-10-06',
  UNIQUE (election_id, election_type, region, sub_region, village)
);
COMMENT ON TABLE election_bulletins IS
  '選舉單位（跟 cec_candidates 同一套寫法）→ 中選會選舉公報的站內路徑；paths 以「01選舉公報/」開頭的在 bulletin.cec.gov.tw，其餘在 eebulletin.cec.gov.tw。對不到的單位不列（2026-10-06）';
COMMENT ON COLUMN election_bulletins.paths IS
  '站內路徑：中文照原樣，空白等不安全字元已轉 %XX；一份為主，正反面或分份最多 4 份（候選人在其中一份上）';
COMMENT ON COLUMN election_bulletins.match_basis IS
  '怎麼對到的：一村里一份／鄉鎮一份／選區／選區（合印或分份）／縣市一份／合印分選區，取第一選區';
ALTER TABLE election_bulletins ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public read" ON election_bulletins;
CREATE POLICY "Public read" ON election_bulletins FOR SELECT USING (true);
DROP POLICY IF EXISTS "Service role write" ON election_bulletins;
CREATE POLICY "Service role write" ON election_bulletins FOR ALL USING (auth.role() = 'service_role');
GRANT SELECT ON election_bulletins TO anon, authenticated;

